def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foreground = next((v for v in counts if v != background), background)
    out = [[background] * w for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] == foreground:
                out[r + 1][c] = foreground
    return out
